<?php
require_once dirname(__DIR__,2).'/includes/bootstrap.php';require_once ROOT_PATH.'/includes/cost_analysis.php';require_login();require_permission('costs.view');$pdo=db();$range=cost_date_range($_GET,date('Y-01-01'),date('Y-12-31'));$s=cost_monthly_series($pdo,$range['start'],$range['end']);$labels=array_column($s,'label');$total=['labels'=>$labels,'datasets'=>[['label'=>'Transportation cost','data'=>array_map('floatval',array_column($s,'cost')),'borderColor'=>'#2F80ED','backgroundColor'=>'rgba(47,128,237,.1)']]];$types=['labels'=>$labels,'datasets'=>[]];foreach([['fuel','Fuel','#2F80ED'],['maintenance','Maintenance','#F2994A'],['toll','Toll','#27AE60'],['driver','Driver allowance','#64748B']] as [$key,$label,$color]){if(array_sum(array_map('floatval',array_column($s,$key)))>0)$types['datasets'][]=['label'=>$label,'data'=>array_map('floatval',array_column($s,$key)),'borderColor'=>$color,'backgroundColor'=>$color];}$rev=['labels'=>$labels,'datasets'=>[['label'=>'Revenue','data'=>array_map('floatval',array_column($s,'revenue')),'borderColor'=>'#27AE60','backgroundColor'=>'rgba(39,174,96,.1)'],['label'=>'Cost','data'=>array_map('floatval',array_column($s,'cost')),'borderColor'=>'#2F80ED','backgroundColor'=>'rgba(47,128,237,.1)']]];$active_page='cost-trends';$body_class=trim(($body_class??'').' cost-analysis-module cost-trends-page');$page_title='Cost Trends';$include_chart=true;require ROOT_PATH.'/includes/header.php';?>
<div class="d-flex flex-wrap justify-content-between align-items-end mb-4 gap-3 cost-page-heading"><div><h1 class="mb-1">Cost Trends</h1><p class="text-muted-custom mb-0">Historical movement of recorded transportation costs.</p></div><form method="get" class="d-flex align-items-end gap-2 cost-filter-form"><div><label class="tc-form-label small">From</label><input class="tc-form-control" type="date" name="from" value="<?=e($range['from'])?>"></div><div><label class="tc-form-label small">To</label><input class="tc-form-control" type="date" name="to" value="<?=e($range['to'])?>"></div><button class="tc-btn tc-btn-primary">Apply</button></form></div>
<div class="row g-3"><div class="col-12"><div class="tc-card p-3"><h2 class="fs-6 fw-bold">Monthly Transportation Cost Trend</h2><div style="height:300px"><canvas id="trend-total"></canvas></div></div></div><div class="col-lg-6"><div class="tc-card p-3 h-100"><h2 class="fs-6 fw-bold">Cost by Type Over Time</h2><?php if($types['datasets']):?><div style="height:300px"><canvas id="trend-types"></canvas></div><?php else:?><div class="text-center text-muted-custom py-5">No transportation cost records for this period.</div><?php endif;?></div></div><div class="col-lg-6"><div class="tc-card p-3 h-100"><h2 class="fs-6 fw-bold">Revenue vs Cost Trend</h2><div style="height:300px"><canvas id="trend-revenue"></canvas></div></div></div></div>
<?php $page_scripts='<script src="'.BASE_URL.'/js/cost-analysis.js?v='.(int)filemtime(ROOT_PATH.'/js/cost-analysis.js').'"></script><script>(function(){if(typeof Chart==="undefined")return;function draw(id,data){const e=document.getElementById(id);if(!e)return;new Chart(e,{type:"line",data,options:{responsive:true,maintainAspectRatio:false,interaction:{mode:"index",intersect:false},plugins:{legend:{position:"bottom"}},scales:{y:{beginAtZero:true,ticks:{callback:v=>(window.fleetCurrencySymbol||"₱")+Number(v).toLocaleString()}},x:{grid:{display:false}}}}})}draw("trend-total",'.json_encode($total,JSON_UNESCAPED_UNICODE).');draw("trend-types",'.json_encode($types,JSON_UNESCAPED_UNICODE).');draw("trend-revenue",'.json_encode($rev,JSON_UNESCAPED_UNICODE).');})();</script>';require ROOT_PATH.'/includes/footer.php';?>
